sealed class HesabyarException: kotlin.Exception() {
    
    class ParseException(
        
        val `detail`: kotlin.String
        ) : HesabyarException() {
        override val message
            get() = "detail=${ `detail` }"
    }
    
    class InvalidAmount(
        
        val `amount`: kotlin.String
        ) : HesabyarException() {
        override val message
            get() = "amount=${ `amount` }"
    }
    
    class InvalidDate(
        
        val `detail`: kotlin.String
        ) : HesabyarException() {
        override val message
            get() = "detail=${ `detail` }"
    }
    
    class BackupValidation(
        
        val `detail`: kotlin.String
        ) : HesabyarException() {
        override val message
            get() = "detail=${ `detail` }"
    }
    
    class CalendarException(
        
        val `detail`: kotlin.String
        ) : HesabyarException() {
        override val message
            get() = "detail=${ `detail` }"
    }
    
    class CryptoException(
        
        val `detail`: kotlin.String
        ) : HesabyarException() {
        override val message
            get() = "detail=${ `detail` }"
    }
    
    class ValidationException(
        
        val `detail`: kotlin.String
        ) : HesabyarException() {
        override val message
            get() = "detail=${ `detail` }"
    }
    

    companion object ErrorHandler : UniffiRustCallStatusErrorHandler<HesabyarException> {
        override fun lift(error_buf: RustBuffer.ByValue): HesabyarException = FfiConverterTypeHesabyarError.lift(error_buf)
    }

    
}

/**
 * @suppress
 */
public object FfiConverterTypeHesabyarError : FfiConverterRustBuffer<HesabyarException> {
    override fun read(buf: ByteBuffer): HesabyarException {
        

        return when(buf.getInt()) {
            1 -> HesabyarException.ParseException(
                FfiConverterString.read(buf),
                )
            2 -> HesabyarException.InvalidAmount(
                FfiConverterString.read(buf),
                )
            3 -> HesabyarException.InvalidDate(
                FfiConverterString.read(buf),
                )
            4 -> HesabyarException.BackupValidation(
                FfiConverterString.read(buf),
                )
            5 -> HesabyarException.CalendarException(
                FfiConverterString.read(buf),
                )
            6 -> HesabyarException.CryptoException(
                FfiConverterString.read(buf),
                )
            7 -> HesabyarException.ValidationException(
                FfiConverterString.read(buf),
                )
            else -> throw RuntimeException("invalid error enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: HesabyarException): ULong {
        return when(value) {
            is HesabyarException.ParseException -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`detail`)
            )
            is HesabyarException.InvalidAmount -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`amount`)
            )
            is HesabyarException.InvalidDate -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`detail`)
            )
            is HesabyarException.BackupValidation -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`detail`)
            )
            is HesabyarException.CalendarException -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`detail`)
            )
            is HesabyarException.CryptoException -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`detail`)
            )
            is HesabyarException.ValidationException -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`detail`)
            )
        }
    }

    override fun write(value: HesabyarException, buf: ByteBuffer) {
        when(value) {
            is HesabyarException.ParseException -> {
                buf.putInt(1)
                FfiConverterString.write(value.`detail`, buf)
                Unit
            }
            is HesabyarException.InvalidAmount -> {
                buf.putInt(2)
                FfiConverterString.write(value.`amount`, buf)
                Unit
            }
            is HesabyarException.InvalidDate -> {
                buf.putInt(3)
                FfiConverterString.write(value.`detail`, buf)
                Unit
            }
            is HesabyarException.BackupValidation -> {
                buf.putInt(4)
                FfiConverterString.write(value.`detail`, buf)
                Unit
            }
            is HesabyarException.CalendarException -> {
                buf.putInt(5)
                FfiConverterString.write(value.`detail`, buf)
                Unit
            }
            is HesabyarException.CryptoException -> {
                buf.putInt(6)
                FfiConverterString.write(value.`detail`, buf)
                Unit
            }
            is HesabyarException.ValidationException -> {
                buf.putInt(7)
                FfiConverterString.write(value.`detail`, buf)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }

}




